from datetime import datetime
from typing import List
from fastapi import APIRouter, Depends, HTTPException
from sqlmodel import Session, select
from app.core.database import get_session
from app.api.endpoints.auth import get_current_user
from app.models.domain import User, Roadmap, DSAProgress
from app.models.schemas import DSAProgressCreate, DSAProgressResponse

router = APIRouter()

@router.get("")
def get_roadmap(current_user: User = Depends(get_current_user), session: Session = Depends(get_session)):
    """Fetch the student's roadmap (weekly and monthly learning plan) generated by the agent."""
    roadmap = session.exec(select(Roadmap).where(Roadmap.user_id == current_user.id)).first()
    if not roadmap:
        return {"weekly_tasks": {}, "monthly_tasks": {}}
    return roadmap


@router.get("/dsa/progress", response_model=List[DSAProgressResponse])
def get_dsa_progress(current_user: User = Depends(get_current_user), session: Session = Depends(get_session)):
    """Retrieve all DSA logs and question statuses for the user."""
    progress = session.exec(select(DSAProgress).where(DSAProgress.user_id == current_user.id)).all()
    return progress


@router.post("/dsa/progress", response_model=DSAProgressResponse)
def log_dsa_progress(
    progress_in: DSAProgressCreate,
    current_user: User = Depends(get_current_user),
    session: Session = Depends(get_session)
):
    """Add or update progress on a DSA question."""
    existing = session.exec(
        select(DSAProgress).where(
            (DSAProgress.user_id == current_user.id) &
            (DSAProgress.question_name == progress_in.question_name)
        )
    ).first()
    
    if existing:
        existing.status = progress_in.status
        if progress_in.status.lower() == "solved":
            existing.solved_at = datetime.utcnow()
        session.add(existing)
        session.commit()
        session.refresh(existing)
        return existing
        
    new_progress = DSAProgress(
        user_id=current_user.id,
        topic=progress_in.topic,
        question_name=progress_in.question_name,
        difficulty=progress_in.difficulty,
        status=progress_in.status,
        solved_at=datetime.utcnow() if progress_in.status.lower() == "solved" else None
    )
    session.add(new_progress)
    session.commit()
    session.refresh(new_progress)
    return new_progress
